"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { creditCostForText } from "@/lib/product-contract";
import type { SanitizeReceipt, TextScanReceipt } from "@/lib/provenance/types";
import { scanText } from "@/lib/provenance/unicode";
import { ForensicTextPreview, OperationStatus } from "./forensic-evidence";
import { emitReceipt } from "./receipt-drawer";
import { TurnstileWidget } from "./turnstile-widget";

const DEMO_TEXT = "A normal sentence\u200B with a hidden zero-width space.\nRTL control example: \u202Ereview me.";

function messageFrom(payload: unknown, fallback: string) {
  if (payload && typeof payload === "object") {
    const error = (payload as { error?: unknown }).error;
    if (typeof error === "string") return error;
    if (error && typeof error === "object" && typeof (error as { message?: unknown }).message === "string") {
      return (error as { message: string }).message;
    }
  }
  return fallback;
}

function downloadJson(payload: unknown, name: string) {
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = name;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

export function ScannerWorkbench() {
  const [text, setText] = useState(DEMO_TEXT);
  const [receipt, setReceipt] = useState<TextScanReceipt | null>(null);
  const [receiptId, setReceiptId] = useState<string | null>(null);
  const [sanitation, setSanitation] = useState<SanitizeReceipt | null>(null);
  const [fileName, setFileName] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [billingNote, setBillingNote] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [online, setOnline] = useState(true);
  const [status, setStatus] = useState<{ state: "idle" | "working" | "complete" | "review"; message: string }>({
    state: "idle",
    message: "Ready when you are.",
  });
  const [challengeToken, setChallengeToken] = useState<string | null>(null);
  const [challengeReset, setChallengeReset] = useState(0);
  const onChallenge = useCallback((token: string | null) => setChallengeToken(token), []);
  const canScan = text.length > 0;
  const estimatedCredits = useMemo(() => creditCostForText(text), [text]);
  const currentScan = useMemo(() => scanText(text), [text]);
  const grouped = useMemo(
    () => receipt ? Object.entries(receipt.summary.byCategory).filter(([, count]) => count > 0) : [],
    [receipt],
  );

  useEffect(() => {
    const sync = () => setOnline(navigator.onLine);
    sync();
    window.addEventListener("online", sync);
    window.addEventListener("offline", sync);
    return () => {
      window.removeEventListener("online", sync);
      window.removeEventListener("offline", sync);
    };
  }, []);

  function replaceText(next: string, sourceFile: string | null = null) {
    setText(next);
    setFileName(sourceFile);
    setReceipt(null);
    setReceiptId(null);
    setSanitation(null);
    setBillingNote(null);
    setError(null);
    setStatus({ state: "idle", message: "Ready when you are." });
  }

  async function loadTxt(file: File | null) {
    if (!file) return;
    if (!file.name.toLowerCase().endsWith(".txt") && file.type !== "text/plain") {
      setError("Choose a plain-text .txt file.");
      return;
    }
    try {
      replaceText(await file.text(), file.name);
    } catch {
      setError("Could not read this text file.");
    }
  }

  function publishScan(next: TextScanReceipt, id: string) {
    emitReceipt({
      id,
      title: "Text inspection receipt",
      operation: fileName ? "txt.scan" : "text.scan",
      status: next.summary.reviewRequired ? "review" : "inspected",
      inputSizeBucket: `${next.input.words} words`,
      findingsDetected: next.summary.total,
      findingsRemoved: 0,
      findingsPreserved: next.summary.total,
      findingsReview: next.summary.reviewRequired,
      verification: "Local deterministic inspection completed. No account or credit mutation was required.",
      details: [
        { label: "Words", value: next.input.words },
        { label: "Safe removals", value: next.summary.safeToRemove },
        { label: "Needs review", value: next.summary.reviewRequired },
      ],
    });
  }

  function runScan() {
    if (!canScan) return;
    setStatus({ state: "working", message: "Inspecting content…" });
    window.requestAnimationFrame(() => {
      const next = scanText(text);
      const id = crypto.randomUUID();
      setReceipt(next);
      setReceiptId(id);
      setSanitation(null);
      setBillingNote(null);
      setStatus({
        state: next.summary.reviewRequired ? "review" : "complete",
        message: next.summary.reviewRequired ? "Inspection complete. Some findings need review." : "Inspection complete.",
      });
      publishScan(next, id);
    });
  }

  function exportReceipt() {
    if (!receipt) return;
    downloadJson({
      version: "text-scan-receipt-v1",
      id: receiptId ?? crypto.randomUUID(),
      input: { kind: fileName ? "txt" : "text", words: receipt.input.words },
      summary: receipt.summary,
      findings: receipt.findings.map((item) => ({
        codePoint: item.codePoint,
        characterName: item.characterName,
        index: item.index,
        category: item.category,
        disposition: item.disposition,
        description: item.description,
      })),
      sanitation: sanitation ? {
        removed: sanitation.removed.length,
        preservedForReview: sanitation.preservedForReview.length,
      } : null,
    }, `provenance-text-receipt-${(receiptId ?? "local").slice(0, 12)}.json`);
  }

  async function cleanConservatively() {
    if (!online) {
      setError("Cleaning requires a network connection because billing and authoritative verification stay server-side.");
      setStatus({ state: "review", message: "Local inspection is still available offline." });
      return;
    }
    if (!challengeToken || !canScan) return;
    setBusy(true);
    setError(null);
    setBillingNote(null);
    setStatus({ state: "working", message: "Preparing verified cleaning…" });

    try {
      const sessionResponse = await fetch("/api/auth/anonymous", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ challengeToken, forClean: true }),
      });
      const sessionPayload = await sessionResponse.json();
      if (!sessionResponse.ok) throw new Error(messageFrom(sessionPayload, "Could not prepare the clean operation."));

      setStatus({ state: "working", message: "Removing safe findings and verifying output…" });
      const response = await fetch("/api/text/sanitize", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ operationId: crypto.randomUUID(), text, kind: fileName ? "txt" : "text" }),
      });
      const payload = await response.json();
      if (!response.ok) throw new Error(messageFrom(payload, "Could not clean this text."));

      const next = payload.sanitation as SanitizeReceipt;
      const verified = scanText(next.output);
      const operationId = String(payload.billing.operationId);
      setSanitation(next);
      setReceipt(verified);
      setReceiptId(operationId);
      setBillingNote(`${payload.billing.creditsCharged} credit${payload.billing.creditsCharged === 1 ? "" : "s"} charged · ${payload.billing.balanceAfter} remaining`);
      setStatus({
        state: verified.summary.safeToRemove === 0 ? "complete" : "review",
        message: verified.summary.safeToRemove === 0 ? "Verified. Safe findings were removed and the output was re-inspected." : "Cleaning finished, but post-clean verification needs review.",
      });

      emitReceipt({
        id: operationId,
        title: "Conservative text cleaning",
        operation: fileName ? "txt.sanitize" : "text.sanitize",
        status: verified.summary.reviewRequired ? "review" : "validated",
        accountState: sessionPayload?.isAnonymous === false ? "registered" : "guest",
        creditsReserved: Number(payload.billing.creditsCharged),
        creditsCommitted: Number(payload.billing.creditsCharged),
        inputSizeBucket: `${currentScan.input.words} words`,
        findingsDetected: currentScan.summary.total,
        findingsRemoved: next.removed.length,
        findingsPreserved: next.preservedForReview.length,
        findingsReview: next.preservedForReview.length,
        verification: verified.summary.safeToRemove === 0
          ? "Post-clean scan confirms all conservatively safe removals are clear."
          : "Post-clean verification requires review.",
        details: [
          { label: "Balance after", value: Number(payload.billing.balanceAfter) },
          { label: "Review preserved", value: next.preservedForReview.length },
        ],
      });
      window.dispatchEvent(new Event("provenance:account-changed"));
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Could not clean this text.");
      setStatus({ state: "review", message: "The clean operation did not produce a verified result." });
    } finally {
      setBusy(false);
      setChallengeToken(null);
      setChallengeReset((value) => value + 1);
    }
  }

  return <section className="workbench" aria-label="Provenance text scanner">
    <div className="panel editor-panel">
      <div className="panel-heading">
        <div><p className="eyebrow">Free text scanner</p><h2>Inspect before you clean.</h2></div>
        <span className="pill local-pill">{online ? "Local inspection · free" : "Offline · local inspection ready"}</span>
      </div>

      <div className="input-toolbar">
        <div className="actions">
          <label className="secondary upload-action">Upload .txt
            <input type="file" accept=".txt,text/plain" hidden onChange={(event) => void loadTxt(event.target.files?.[0] ?? null)} />
          </label>
          <button className="ghost" onClick={() => replaceText(DEMO_TEXT)}>Try example</button>
          {fileName && <span className="pill">TXT input</span>}
        </div>
        <span className="mono-label">{currentScan.input.words} WORDS</span>
      </div>

      <textarea value={text} onChange={(event) => replaceText(event.target.value)} spellCheck={false} aria-label="Text to scan" />

      <div className="actions primary-actions">
        <button className="primary" onClick={runScan} disabled={!canScan}>Scan text — free</button>
        <button className="secondary" onClick={() => void cleanConservatively()} disabled={!canScan || busy || !challengeToken || !online}>
          {busy ? "Cleaning…" : `Clean safe findings · ${estimatedCredits} usage unit${estimatedCredits === 1 ? "" : "s"}`}
        </button>
        <button className="ghost" onClick={() => replaceText("")}>Clear</button>
      </div>

      {online && <TurnstileWidget action="account" onToken={onChallenge} resetKey={challengeReset} />}
      {!online && <div className="notice-card" role="status"><strong>Offline mode is active.</strong> Scan and receipt export stay local. Billable cleaning, accounts, payments, and model-backed actions are disabled until connectivity returns.</div>}
      <OperationStatus state={status.state} message={status.message} />

      <div className="trust-note">
        <span className="status-dot"/>
        <div><strong>Scan stays local{online ? "." : " — even offline."}</strong><p>Receipt export is generated in your browser. A guest is created only when a billable clean actually needs authoritative credit state. Raw text is not intentionally persisted or cached by the offline shell.</p></div>
      </div>
      {billingNote && <div className="success-card">{billingNote}</div>}
      {error && <div className="error-card" role="alert">{error}</div>}
    </div>

    <div className="panel receipt-panel" aria-label="Verification receipt">
      <div className="panel-heading">
        <div><p className="eyebrow">Verification receipt</p><h2>{receipt ? `${receipt.summary.total} finding${receipt.summary.total === 1 ? "" : "s"}` : "Ready to scan"}</h2></div>
        {receipt && <span className={`score ${receipt.summary.reviewRequired ? "warn" : "ok"}`}>{receipt.summary.reviewRequired ? "Review" : "Clean"}</span>}
      </div>

      {!receipt ? <div className="empty-state">
        <div><span className="empty-symbol">⌁</span><strong>No evidence yet</strong><p>Paste text or upload a .txt file. A free local scan reveals exact code points, positions, and removal safety.</p></div>
      </div> : <>
        <div className="result-summary-card">
          <div><span>Outcome</span><strong>{receipt.summary.reviewRequired ? "Review required" : "No review required"}</strong></div>
          <p>{receipt.summary.safeToRemove} safe removal{receipt.summary.safeToRemove === 1 ? "" : "s"} · {receipt.summary.reviewRequired} item{receipt.summary.reviewRequired === 1 ? "" : "s"} to review</p>
        </div>

        <div className="metrics">
          <Metric label="Words" value={receipt.input.words} />
          <Metric label="Safe removals" value={receipt.summary.safeToRemove} />
          <Metric label="Needs review" value={receipt.summary.reviewRequired} />
        </div>

        {grouped.length > 0 && <details className="evidence-disclosure">
          <summary>Technical categories <span>{grouped.length}</span></summary>
          <div className="category-row">{grouped.map(([category, count]) => <span className="category" key={category}>{category.replaceAll("_", " ")} · {count}</span>)}</div>
        </details>}

        <ForensicTextPreview text={text} findings={receipt.findings} />

        <div className="receipt-tools">
          <button className="ghost" type="button" onClick={exportReceipt}>Export JSON receipt</button>
          {receiptId && <button className="ghost" type="button" onClick={() => publishScan(receipt, receiptId)}>View receipt</button>}
        </div>
      </>}

      {sanitation && <div className="clean-output">
        <div className="output-heading"><strong>Conservative cleaned output</strong><button className="copy" onClick={() => navigator.clipboard.writeText(sanitation.output)}>Copy</button></div>
        <pre>{sanitation.output || "(empty)"}</pre>
        <p>{sanitation.removed.length} removed · {sanitation.preservedForReview.length} preserved for review · post-clean scan {scanText(sanitation.output).summary.safeToRemove === 0 ? "safe removals clear" : "failed"}</p>
      </div>}
    </div>
  </section>;
}

function Metric({ label, value }: { label: string; value: number }) {
  return <div className="metric"><span>{label}</span><strong>{value}</strong></div>;
}

import { expect, test } from "@playwright/test";

const ANALYTICS_HOSTS = /posthog|google-analytics|googletagmanager|segment\.io|mixpanel|plausible|amplitude/i;

async function assertNoHorizontalOverflow(page: import("@playwright/test").Page) {
  const dimensions = await page.evaluate(() => ({ width: window.innerWidth, scrollWidth: document.documentElement.scrollWidth }));
  expect(dimensions.scrollWidth).toBeLessThanOrEqual(dimensions.width + 1);
}

test("DNT does not emit third-party analytics from the public workbench", async ({ page }) => {
  await page.addInitScript(() => {
    Object.defineProperty(Navigator.prototype, "doNotTrack", { configurable: true, get: () => "1" });
  });
  const analyticsRequests: string[] = [];
  page.on("request", request => { if (ANALYTICS_HOSTS.test(request.url())) analyticsRequests.push(request.url()); });
  await page.goto("/", { waitUntil: "networkidle" });
  expect(await page.evaluate(() => navigator.doNotTrack)).toBe("1");
  expect(analyticsRequests).toEqual([]);
});

test("homepage makes the workbench primary and explains the operating model", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByRole("heading", { level: 1, name: /Know what your content is carrying/i })).toBeVisible();
  const model = page.locator(".app-intro-meta");
  await expect(model.getByText("INSPECT", { exact: true })).toBeVisible();
  await expect(model.getByText("ACT", { exact: true })).toBeVisible();
  await expect(model.getByText("VERIFY", { exact: true })).toBeVisible();
  await expect(page.getByRole("link", { name: "Verification model" })).toBeVisible();
  await expect(page.getByRole("link", { name: "Usage & pricing" })).toBeVisible();
  await expect(page.getByRole("tab", { name: /^Text/i })).toBeVisible();
  await expect(page.getByRole("region", { name: "Provenance text scanner" })).toBeVisible();
});

test("source canary is not persisted in browser storage after a free scan", async ({ page }) => {
  const canary = `PC_PRIVACY_TEXT_${crypto.randomUUID()}`;
  await page.goto("/");
  const scanner = page.getByRole("region", { name: "Provenance text scanner" });
  await scanner.getByLabel("Text to scan").fill(`${canary}\u200B`);
  await scanner.getByRole("button", { name: "Scan text" }).click();
  await expect(scanner.getByText(/finding/i).first()).toBeVisible();

  const persisted = await page.evaluate(async marker => {
    const local = Object.entries(localStorage).map(([key, value]) => `${key}:${value}`).join("\n");
    const session = Object.entries(sessionStorage).map(([key, value]) => `${key}:${value}`).join("\n");
    const databases = typeof indexedDB.databases === "function" ? await indexedDB.databases() : [];
    const cacheNames = "caches" in window ? await caches.keys() : [];
    return {
      local: local.includes(marker),
      session: session.includes(marker),
      indexedDbName: databases.some(item => item.name?.includes(marker)),
      cacheName: cacheNames.some(name => name.includes(marker)),
      cookie: document.cookie.includes(marker),
    };
  }, canary);
  expect(persisted).toEqual({ local: false, session: false, indexedDbName: false, cacheName: false, cookie: false });
});

test("unicode findings map to an interactive source preview", async ({ page }) => {
  await page.goto("/");
  const scanner = page.getByRole("region", { name: "Provenance text scanner" });
  await scanner.getByLabel("Text to scan").fill("Contract signed\u200B today. Review \u202Ethis marker.");
  await scanner.getByRole("button", { name: "Scan text" }).click();

  const explorer = scanner.getByTestId("forensic-text-explorer");
  await expect(explorer).toBeVisible();
  const marker = explorer.getByRole("button", { name: "Select U+200B at index 15", exact: true });
  await expect(marker).toBeVisible();
  await marker.click();
  await expect(marker).toHaveAttribute("aria-pressed", "true");
  await expect(explorer.getByLabel("Selected finding source preview")).toContainText("[U+200B]");
  await expect(explorer.getByLabel("Selected finding source preview")).toContainText("ZERO WIDTH SPACE");
});

test("free scan creates an accessible exportable receipt drawer without persisting source text", async ({ page }) => {
  const canary = `PC_RECEIPT_${crypto.randomUUID()}`;
  await page.goto("/");
  const scanner = page.getByRole("region", { name: "Provenance text scanner" });
  await scanner.getByLabel("Text to scan").fill(`${canary}\u200B review`);
  await scanner.getByRole("button", { name: "Scan text" }).click();
  const latestReceipt = page.getByRole("button", { name: "View latest verification receipt" });
  await expect(latestReceipt).toBeVisible();
  await latestReceipt.click();
  const dialog = page.getByRole("dialog", { name: "Text inspection receipt" });
  await expect(dialog).toBeVisible();
  await expect(dialog.getByText("text.scan")).toBeVisible();
  await expect(dialog.getByText("Inspection complete.")).toBeVisible();
  await expect(dialog.getByRole("button", { name: "Export JSON receipt" })).toBeVisible();
  await expect(dialog.getByText("Technical evidence")).toBeVisible();
  await expect(dialog).not.toContainText(canary);
});

test("mobile navigation remains available and keyboard dismissible", async ({ page }) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto("/");
  const trigger = page.locator('button[aria-controls="mobile-navigation"]');
  await expect(trigger).toBeVisible();
  await expect(trigger).toHaveAttribute("aria-label", "Open navigation");
  await trigger.click();
  await expect(trigger).toHaveAttribute("aria-expanded", "true");
  await expect(trigger).toHaveAttribute("aria-label", "Close navigation");
  const mobileContainer = page.locator("#mobile-navigation");
  const mobileNav = mobileContainer.getByRole("navigation", { name: "Mobile primary" });
  await expect(mobileNav).toBeVisible();
  await expect(mobileNav.getByRole("link", { name: /Workbench/ })).toBeVisible();
  await expect(mobileContainer.getByRole("link", { name: "Open workspace" })).toBeVisible();
  await page.keyboard.press("Escape");
  await expect(trigger).toHaveAttribute("aria-expanded", "false");
  await expect(trigger).toHaveAttribute("aria-label", "Open navigation");
  await assertNoHorizontalOverflow(page);
});

test("contact message stays client-side and only prepares mailto behavior", async ({ page }) => {
  const canary = `PC_CONTACT_${crypto.randomUUID()}`;
  const applicationPosts: string[] = [];
  page.on("request", request => {
    if (request.method() === "POST" && new URL(request.url()).origin === "http://127.0.0.1:3000") applicationPosts.push(request.url());
  });
  await page.goto("/contact");
  await page.getByLabel("Subject").fill("Privacy test");
  await page.getByLabel("Message").fill(canary);
  const submit = page.getByRole("button", { name: "Send message" });
  await expect(submit).toBeEnabled();
  await submit.click();
  await page.waitForTimeout(250);
  expect(applicationPosts).toEqual([]);
  expect(await page.evaluate(marker => document.documentElement.innerHTML.includes(marker), canary)).toBe(true);
});

test("refinement breakpoints keep the workbench intentional and overflow-free", async ({ page }) => {
  const widths = [360, 375, 390, 430, 768, 820, 1024, 1180, 1440];
  for (const width of widths) {
    await page.setViewportSize({ width, height: 900 });
    const response = await page.goto("/", { waitUntil: "domcontentloaded" });
    expect(response?.status()).toBeLessThan(400);
    await expect(page.getByRole("main")).toBeVisible();
    await expect(page.getByRole("region", { name: "Provenance text scanner" })).toBeVisible();
    await assertNoHorizontalOverflow(page);
  }
});

test("public surfaces have main landmarks and no horizontal overflow across launch widths", async ({ page }) => {
  test.setTimeout(120_000);
  const widths = [375, 768, 1440];
  const routes = ["/", "/pricing", "/auth", "/contact", "/privacy-policy", "/terms-of-service", "/cookie-policy", "/faq", "/how-it-works", "/capabilities", "/mission"];
  for (const width of widths) {
    await page.setViewportSize({ width, height: 900 });
    for (const route of routes) {
      const response = await page.goto(route, { waitUntil: "domcontentloaded" });
      expect(response?.status(), `${route} should be a public route`).toBeLessThan(400);
      await expect(page.locator("main").first(), `${route} should expose a main landmark`).toBeVisible();
      await assertNoHorizontalOverflow(page);
    }
  }
});

test("core workbench is keyboard reachable and exposes accessible async regions across tabs", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByRole("region", { name: "Account and credits" })).toBeVisible();
  await expect(page.getByRole("region", { name: "Provenance text scanner" })).toBeVisible();

  const filesTab = page.getByRole("tab", { name: /^Files/i });
  await filesTab.click();
  await expect(filesTab).toHaveAttribute("aria-selected", "true");
  await expect(page.getByRole("region", { name: "File metadata scanner" })).toBeVisible();

  const rewriteTab = page.getByRole("tab", { name: /^Rewrite/i });
  await rewriteTab.click();
  await expect(rewriteTab).toHaveAttribute("aria-selected", "true");
  const editor = page.getByRole("region", { name: "Semantics-preserving editor" });
  await expect(editor).toBeVisible();
  await expect(editor.locator('[aria-live="polite"]')).toHaveCount(1);

  await page.keyboard.press("Tab");
  const focused = await page.evaluate(() => document.activeElement?.tagName ?? null);
  expect(focused).not.toBe("BODY");
});

import type {
  FindingCategory,
  FindingDisposition,
  SanitizeReceipt,
  TextFinding,
  TextScanReceipt,
} from "./types";

type Rule = {
  category: FindingCategory;
  disposition: FindingDisposition;
  name: string;
  description: string;
};

const EXACT_RULES = new Map<number, Rule>([
  [0x200b, { category: "zero_width", disposition: "safe_remove", name: "ZERO WIDTH SPACE", description: "Invisible spacing character that is usually unnecessary in ordinary prose." }],
  [0xfeff, { category: "zero_width", disposition: "safe_remove", name: "ZERO WIDTH NO-BREAK SPACE / BOM", description: "Usually safe to remove when embedded inside pasted text." }],
  [0x200c, { category: "format_control", disposition: "review", name: "ZERO WIDTH NON-JOINER", description: "May be linguistically meaningful in Persian, Arabic, Indic scripts, and other writing systems." }],
  [0x200d, { category: "format_control", disposition: "review", name: "ZERO WIDTH JOINER", description: "May be meaningful in emoji sequences and several writing systems." }],
  [0x2060, { category: "format_control", disposition: "review", name: "WORD JOINER", description: "Invisible formatting control; review before removal because it can express line-breaking intent." }],
  [0x00a0, { category: "unusual_space", disposition: "review", name: "NO-BREAK SPACE", description: "Common in copied web content and typography; not removed in conservative mode." }],
  [0x202f, { category: "unusual_space", disposition: "review", name: "NARROW NO-BREAK SPACE", description: "Used legitimately in typography and some languages." }],
]);

function rangeRule(codePoint: number): Rule | null {
  if (codePoint >= 0x202a && codePoint <= 0x202e) {
    return {
      category: "bidi_control",
      disposition: "review",
      name: "BIDIRECTIONAL EMBEDDING/OVERRIDE CONTROL",
      description: "Directionality control. It can be legitimate in bidirectional text and can also conceal text ordering changes.",
    };
  }
  if (codePoint >= 0x2066 && codePoint <= 0x2069) {
    return {
      category: "bidi_control",
      disposition: "review",
      name: "BIDIRECTIONAL ISOLATE CONTROL",
      description: "Directionality isolate. Preserve by default unless the document is known not to require RTL/BiDi formatting.",
    };
  }
  if (codePoint >= 0xe0000 && codePoint <= 0xe007f) {
    return {
      category: "unicode_tag",
      disposition: "review",
      name: "UNICODE TAG CHARACTER",
      description: "Invisible tag-plane character. Some emoji flag sequences use tags, so removal requires review.",
    };
  }
  if (
    (codePoint >= 0x2000 && codePoint <= 0x200a) ||
    codePoint === 0x205f ||
    codePoint === 0x3000
  ) {
    return {
      category: "unusual_space",
      disposition: "review",
      name: "TYPOGRAPHIC SPACE",
      description: "Non-ASCII spacing character. It may be intentional typography.",
    };
  }
  return null;
}

function classify(codePoint: number): Rule | null {
  return EXACT_RULES.get(codePoint) ?? rangeRule(codePoint);
}

function wordCount(text: string): number {
  const trimmed = text.trim();
  return trimmed ? trimmed.split(/\s+/u).length : 0;
}

export function scanText(text: string, scannedAt = new Date().toISOString()): TextScanReceipt {
  const findings: TextFinding[] = [];
  let utf16Index = 0;

  for (const char of text) {
    const codePoint = char.codePointAt(0)!;
    const rule = classify(codePoint);
    if (rule) {
      findings.push({
        id: `u-${utf16Index}-${codePoint.toString(16)}`,
        category: rule.category,
        disposition: rule.disposition,
        index: utf16Index,
        codePoint: `U+${codePoint.toString(16).toUpperCase().padStart(4, "0")}`,
        characterName: rule.name,
        description: rule.description,
      });
    }
    utf16Index += char.length;
  }

  const byCategory: TextScanReceipt["summary"]["byCategory"] = {
    zero_width: 0,
    bidi_control: 0,
    unicode_tag: 0,
    unusual_space: 0,
    format_control: 0,
  };
  for (const finding of findings) byCategory[finding.category] += 1;

  return {
    version: "text-scan-v1",
    scannedAt,
    input: {
      characters: text.length,
      codePoints: Array.from(text).length,
      words: wordCount(text),
    },
    findings,
    summary: {
      total: findings.length,
      safeToRemove: findings.filter((f) => f.disposition === "safe_remove").length,
      reviewRequired: findings.filter((f) => f.disposition === "review").length,
      byCategory,
    },
  };
}

export function sanitizeText(
  text: string,
  mode: SanitizeReceipt["mode"] = "conservative",
): SanitizeReceipt {
  const scan = scanText(text);
  const removed: TextFinding[] = [];
  const preservedForReview: TextFinding[] = [];
  const findingsByIndex = new Map(scan.findings.map((finding) => [finding.index, finding]));
  let output = "";
  let utf16Index = 0;

  for (const char of text) {
    const cp = char.codePointAt(0)!;
    const rule = classify(cp);
    if (!rule) {
      output += char;
      utf16Index += char.length;
      continue;
    }

    const finding = findingsByIndex.get(utf16Index);
    const shouldRemove = rule.disposition === "safe_remove" || mode === "aggressive";

    if (shouldRemove) {
      if (finding) removed.push(finding);
    } else {
      output += char;
      if (finding) preservedForReview.push(finding);
    }
    utf16Index += char.length;
  }

  return { mode, removed, preservedForReview, output };
}

import { ascii } from "./binary";
import { inspectDocx, sanitizeDocx } from "./docx";
import { inspectJpeg, inspectPng, inspectWebp } from "./image";
import { inspectPdf } from "./pdf";
import type { FileFinding, FileInspectionReceipt, FileSanitizeResult, SupportedFileFormat } from "./types";

const MIME: Record<SupportedFileFormat, string> = {
  jpeg: "image/jpeg",
  png: "image/png",
  webp: "image/webp",
  docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  pdf: "application/pdf",
};

export function detectFileFormat(bytes: Uint8Array, name = ""): SupportedFileFormat {
  if (bytes[0] === 0xff && bytes[1] === 0xd8) return "jpeg";
  if (bytes[0] === 137 && ascii(bytes, 1, 4) === "PNG") return "png";
  if (ascii(bytes, 0, 4) === "RIFF" && ascii(bytes, 8, 12) === "WEBP") return "webp";
  if (ascii(bytes, 0, 5) === "%PDF-") return "pdf";
  if (bytes[0] === 0x50 && bytes[1] === 0x4b && /\.docx$/i.test(name)) return "docx";
  throw new Error("Unsupported file type. Use JPEG, PNG, WebP, DOCX, or PDF.");
}

function summarize(findings: FileFinding[]) {
  return {
    total: findings.length,
    privacyMetadata: findings.filter((item) => item.disposition === "privacy_metadata").length,
    provenance: findings.filter((item) => item.disposition === "provenance").length,
    reviewRequired: findings.filter((item) => item.disposition === "review").length,
    removableByDefault: findings.filter((item) => item.removableByDefault).length,
  };
}

export function inspectFile(bytes: Uint8Array, name: string, scannedAt = new Date().toISOString()): FileInspectionReceipt {
  const format = detectFileFormat(bytes, name);
  let findings: FileFinding[];
  if (format === "jpeg") findings = inspectJpeg(bytes).findings;
  else if (format === "png") findings = inspectPng(bytes).findings;
  else if (format === "webp") findings = inspectWebp(bytes).findings;
  else if (format === "docx") findings = inspectDocx(bytes);
  else findings = inspectPdf(bytes);

  const summary = summarize(findings);
  const hasProvenance = summary.provenance > 0;

  return {
    version: "file-scan-v1",
    scannedAt,
    file: { name, format, mimeType: MIME[format], bytes: bytes.length },
    findings,
    summary,
    capabilities: {
      inspect: true,
      sanitize: format !== "pdf" && !hasProvenance,
      provenanceRemoval: false,
    },
  };
}

function sanitizedName(name: string) {
  const index = name.lastIndexOf(".");
  return index > 0 ? `${name.slice(0, index)}.clean${name.slice(index)}` : `${name}.clean`;
}

export function sanitizeFile(bytes: Uint8Array, name: string): FileSanitizeResult {
  const before = inspectFile(bytes, name);
  const format = before.file.format;
  if (format === "pdf") throw new Error("PDF sanitization is intentionally disabled in Phase 1; inspection is available.");
  if (before.summary.provenance > 0) {
    throw new Error("Sanitization is blocked because provenance metadata may be cryptographically bound to the original asset bytes. Verify Content Credentials before editing the file.");
  }

  let output: Uint8Array;
  if (format === "jpeg") output = inspectJpeg(bytes).sanitize();
  else if (format === "png") output = inspectPng(bytes).sanitize();
  else if (format === "webp") output = inspectWebp(bytes).sanitize();
  else output = sanitizeDocx(bytes);

  const after = inspectFile(output, sanitizedName(name));
  const removedIds = new Set(before.findings.filter((item) => item.removableByDefault).map((item) => item.id));
  return {
    version: "file-sanitize-v1",
    output,
    outputFileName: sanitizedName(name),
    mimeType: before.file.mimeType,
    removed: before.findings.filter((item) => removedIds.has(item.id)),
    preserved: before.findings.filter((item) => !item.removableByDefault),
    before,
    after,
  };
}

